WITH base AS (SELECT * FROM products WHERE NOT (launch_date >= '2025-01-01' AND product_name LIKE 'D%' AND product_name LIKE 'wi%')), Summary AS (SELECT category, COUNT(CASE WHEN category = 'Books' THEN 1 END) AS books_count, SORT_ARRAY(COLLECT_SET(category)) AS category_list FROM base GROUP BY category) SELECT * FROM Summary WHERE books_count >= 5 ORDER BY books_count DESC, category LIMIT 3
